import{_ as s,o as e,c as i,a2 as t}from"./chunks/framework.DfdKBe4j.js";const k=JSON.parse('{"title":"Manage datasets","description":"","frontmatter":{},"headers":[],"relativePath":"guide/datasets.md","filePath":"guide/datasets.md","lastUpdated":1788996123000}'),n={name:"guide/datasets.md"};function d(o,a,h,p,r,l){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="manage-datasets" tabindex="-1">Manage datasets <a class="header-anchor" href="#manage-datasets" aria-label="Permalink to &quot;Manage datasets&quot;">​</a></h1><p>Boomerangz reads policy from locally configured <code>org.boomerangz:*</code> ZFS user properties. A dataset remains unmanaged until <code>org.boomerangz:enabled=on</code> applies to it.</p><h2 id="inspect-before-changing" tabindex="-1">Inspect before changing <a class="header-anchor" href="#inspect-before-changing" aria-label="Permalink to &quot;Inspect before changing&quot;">​</a></h2><p>List discovered datasets and inspect one effective policy:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dataset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dataset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inspect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tank/data</span></span></code></pre></div><p>These commands are read-only and produce human-readable output by default. <code>dataset list</code> labels each dataset as <code>active</code>, <code>inactive</code>, <code>covered</code>, or <code>invalid</code>; when a policy is invalid, inspect that dataset for the reported errors. <code>dataset inspect</code> shows activation and validation status, effective policy, property provenance, recursive-replication coverage, warnings, and errors.</p><p>Add <code>--json</code> when a script or other structured consumer needs the stable JSON representation:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dataset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dataset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inspect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tank/data</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><h2 id="set-a-snapshot-policy" tabindex="-1">Set a snapshot policy <a class="header-anchor" href="#set-a-snapshot-policy" aria-label="Permalink to &quot;Set a snapshot policy&quot;">​</a></h2><p>A policy is a comma-separated grid of <code>count x duration</code> tiers:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> org.boomerangz:policy=12x5m,24x1h,14x1d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tank/data</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> org.boomerangz:enabled=on</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tank/data</span></span></code></pre></div><p>The shortest duration is the snapshot cadence. In this example Boomerangz takes a snapshot every five minutes, keeps progressively fewer snapshots as they age, and retains coverage through the daily tier.</p><p>Supported duration units are:</p><table tabindex="0"><thead><tr><th>Unit</th><th>Meaning</th></tr></thead><tbody><tr><td><code>m</code></td><td>minute</td></tr><tr><td><code>h</code></td><td>hour</td></tr><tr><td><code>d</code></td><td>24-hour day</td></tr><tr><td><code>w</code></td><td>seven days</td></tr><tr><td><code>mo</code></td><td>30 days</td></tr><tr><td><code>y</code></td><td>365 days</td></tr></tbody></table><p>These are elapsed durations rather than calendar boundaries. For example, <code>12mo</code> is 360 days and is not the same duration as <code>1y</code>.</p><h2 id="inheritance" tabindex="-1">Inheritance <a class="header-anchor" href="#inheritance" aria-label="Permalink to &quot;Inheritance&quot;">​</a></h2><p>ZFS properties normally pass from a parent dataset to its children. This is useful when one policy should cover a hierarchy:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> org.boomerangz:policy=24x1h,14x1d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tank/home</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> org.boomerangz:enabled=on</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tank/home</span></span></code></pre></div><p>Set <code>org.boomerangz:enabled=off</code> locally on a child to exclude it. Inspect parents and children before enabling a broad root.</p><h2 id="add-destinations" tabindex="-1">Add destinations <a class="header-anchor" href="#add-destinations" aria-label="Permalink to &quot;Add destinations&quot;">​</a></h2><p>Select configured remote destinations by name:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  org.boomerangz:discard=first</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  org.boomerangz:remote=home-backup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  tank/data</span></span></code></pre></div><p>For a destination dataset on the same host:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  org.boomerangz:discard=first</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  org.boomerangz:local=backup/data</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  tank/data</span></span></code></pre></div><p><code>first</code> is recommended when the configured local or remote root is a persistent destination container. The default <code>off</code> instead treats that configured path as the exact, replica-owned receive dataset; it must initially be absent and its receive permissions must be delegated on the parent. Review the <a href="/v0.1.2/reference/properties#receive-path-mapping">receive path mapping</a> before selecting a destination.</p><p>Multiple names are comma-separated. Empty entries and unknown remote names make the affected policy invalid. Configure and secure the destination before selecting it.</p><h2 id="recursive-replication" tabindex="-1">Recursive replication <a class="header-anchor" href="#recursive-replication" aria-label="Permalink to &quot;Recursive replication&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> org.boomerangz:replicate=on</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tank/data</span></span></code></pre></div><p>Recursive replication explicitly includes all descendant datasets and their snapshots. This includes a descendant with <code>enabled=off</code>: that setting excludes the descendant from independent management, but it does not exclude the dataset from an ancestor&#39;s recursive ZFS replication package. Recursive replication can also carry snapshots not created by Boomerangz, and receive behavior can remove destination snapshots that are absent from the source package. Enable it only after reviewing the complete hierarchy and testing the destination mapping.</p><h2 id="deactivate-a-dataset" tabindex="-1">Deactivate a dataset <a class="header-anchor" href="#deactivate-a-dataset" aria-label="Permalink to &quot;Deactivate a dataset&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> org.boomerangz:enabled=off</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tank/data</span></span></code></pre></div><p>Deactivation stops new management but does not immediately remove recovery state. By default, the dataset remains recoverable for 24 hours before automatic retirement becomes eligible. Change that delay with <code>daemon.inactive_grace_period</code>; set it to <code>0s</code> to disable automatic retirement.</p><p>Re-enable the dataset during the grace period to resume management without discarding its established history.</p><p>See the <a href="/v0.1.2/reference/properties">property reference</a> for every available setting.</p>`,34)])])}const g=s(n,[["render",d]]);export{k as __pageData,g as default};
